79	static clock_t wdt_now(void)
80	{
81	  return clock_systime_ticks();
82	}
83	
84	static uint32_t wdt_age_ms(clock_t last)
85	{
86	  clock_t now = wdt_now();
87	  clock_t dt = now - last;
88	
89	  /* 滴答回退时 unsigned 下溢，会误判心跳过期而停喂狗。 */
90	  if (dt > ((clock_t)-1 / 2))
91	    {
92	      return 0;
93	    }
94	
95	  return (uint32_t)TICK2MSEC(dt);
96	}
97	
98	static bool wdt_fresh(clock_t last)
99	{
100	  return wdt_age_ms(last) < (uint32_t)CONFIG_MYVENDOR_WATCHDOG_HEARTBEAT_MS;
101	}
102	
103	static bool wdt_ui_required_now(void)
104	{
105	  if (g_ui_seen)
106	    {
107	      return true;
108	    }
109	
110	#if defined(CONFIG_MYVENDOR_BICYCLE_AUTOSTART) && CONFIG_MYVENDOR_BICYCLE_AUTOSTART
111	  return wdt_age_ms(g_start_tick) >=
112	         (uint32_t)CONFIG_MYVENDOR_WATCHDOG_UI_GRACE_MS;
113	#else
114	  return false;
115	#endif
116	}
