118	static bool wdt_should_feed(void)
119	{
120	  bool cpu_ok;
121	  bool ui_req;
122	  bool ui_ok;
123	
124	  if (g_suppressed)
125	    {
126	      return false;
127	    }
128	
129	  cpu_ok = wdt_fresh(g_idle_beat) ||
130	           (g_work_seen && wdt_fresh(g_work_beat));
131	  ui_req = wdt_ui_required_now();
132	  ui_ok = !ui_req || (g_ui_seen && wdt_fresh(g_ui_beat)) ||
133	          (g_work_seen && wdt_fresh(g_work_beat));
134	
135	  g_ui_required = ui_req;
136	  return cpu_ok && ui_ok;
137	}
