139	static int wdt_hw_start_now(void)
140	{
141	  int fd;
142	
143	  fd = open(WDT_DEVPATH, O_RDONLY);
144	  if (fd < 0)
145	    {
146	      syslog(LOG_ERR, "[wdt] open %s failed errno=%d\n", WDT_DEVPATH, errno);
147	      return ERROR;
148	    }
149	
150	  if (ioctl(fd, WDIOC_SETTIMEOUT,
151	            (unsigned long)CONFIG_MYVENDOR_WATCHDOG_TIMEOUT_MS) < 0)
152	    {
153	      syslog(LOG_WARNING, "[wdt] SETTIMEOUT(%u) errno=%d\n",
154	             (unsigned)CONFIG_MYVENDOR_WATCHDOG_TIMEOUT_MS, errno);
155	    }
156	
157	  if (ioctl(fd, WDIOC_START, 0) < 0)
158	    {
159	      syslog(LOG_ERR, "[wdt] START errno=%d\n", errno);
160	      close(fd);
161	      return ERROR;
162	    }
163	
164	  close(fd);
165	  g_started = true;
166	  syslog(LOG_INFO,
167	         "[wdt] IWDT start timeout=%ums clk=%uHz feed=%ums heartbeat=%ums\n",
168	         (unsigned)CONFIG_MYVENDOR_WATCHDOG_TIMEOUT_MS,
169	         (hwp_pmuc->CR & PMUC_CR_SEL_LPCLK) ? 32768u : 9000u,
170	         (unsigned)CONFIG_MYVENDOR_WATCHDOG_FEED_MS,
171	         (unsigned)CONFIG_MYVENDOR_WATCHDOG_HEARTBEAT_MS);
172	  return OK;
173	}
