337	void myvendor_watchdog_start(void)
338	{
339	  static bool spawned;
340	  int pid;
341	  clock_t now = wdt_now();
342	
343	  if (spawned)
344	    {
345	      return;
346	    }
347	
348	  g_idle_beat = now;
349	  g_work_beat = 0;
350	  g_start_tick = now;
351	  g_ui_beat = 0;
352	  g_ui_seen = false;
353	  g_work_seen = false;
354	  g_busy_yield_tick = 0;
355	  g_suppressed = false;
356	  g_feeding = false;
357	  g_started = false;
358	
359	  if (wdt_hw_start_now() < 0)
360	    {
361	      return;
362	    }
363	
364	  pid = task_create_with_stack(WDT_FEED_TASK_NAME, WDT_FEED_PRIORITY,
365	                               g_wdt_feed_stack, sizeof(g_wdt_feed_stack),
366	                               wdt_feed_task, NULL);
367	  if (pid < 0)
368	    {
369	      syslog(LOG_ERR, "[wdt] task_create failed errno=%d\n", errno);
370	      return;
371	    }
372	
373	  spawned = true;
374	  syslog(LOG_INFO, "[wdt] feeder pid=%d prio=%d\n",
375	         pid, WDT_FEED_PRIORITY);
376	}
