105	static int sound_pwm_calc(uint16_t hz, uint32_t *prescaler, uint32_t *period,
106	                          uint32_t *pulse)
107	{
108	  uint32_t timclk;
109	  uint64_t ticks;
110	  uint32_t psc;
111	  uint32_t arr;
112	  uint32_t ccr;
113	
114	  if (hz < SOUND_PWM_HZ_MIN) {
115	    hz = SOUND_PWM_HZ_MIN;
116	  } else if (hz > SOUND_PWM_HZ_MAX) {
117	    hz = SOUND_PWM_HZ_MAX;
118	  }
119	
120	  timclk = sound_pwm_timclk();
121	  if (timclk == 0) {
122	    return -EIO;
123	  }
124	
125	  ticks = (uint64_t)timclk / (uint64_t)hz;
126	  if (ticks == 0) {
127	    ticks = 1;
128	  }
129	
130	  psc = (uint32_t)((ticks + 65535ULL - 1ULL) / 65535ULL);
131	  if (psc == 0) {
132	    psc = 1;
133	  }
134	
135	  arr = (uint32_t)(ticks / psc);
136	  if (arr < 2) {
137	    arr = 2;
138	  } else if (arr > 65535) {
139	    arr = 65535;
140	  }
141	
142	  ccr = (uint32_t)(((uint64_t)g_pwm_duty_pct * (uint64_t)arr) / 100ULL);
143	  if (ccr == 0) {
144	    ccr = 1;
145	  } else if (ccr >= arr) {
146	    ccr = arr - 1;
147	  }
148	
149	  *prescaler = psc;
150	  *period = arr;
151	  *pulse = ccr;
152	  return 0;
153	}
