157	static int sound_pwm_init_once(void)
158	{
159	  GPT_OC_InitTypeDef oc_cfg;
160	  uint32_t psc;
161	  uint32_t arr;
162	  uint32_t ccr;
163	
164	  if (g_pwm_ready) {
165	    return 0;
166	  }
167	
168	  memset(&g_pwm, 0, sizeof(g_pwm));
169	  g_pwm.Instance = GPTIM2;
170	  g_pwm.core = GPTIM2_CORE;
171	  HAL_RCC_EnableModule(RCC_MOD_GPTIM2);
172	
173	  if (sound_pwm_calc(SOUND_F0, &psc, &arr, &ccr) != 0) {
174	    return -EIO;
175	  }
176	
177	  g_pwm.Init.Prescaler = psc - 1;
178	  g_pwm.Init.CounterMode = GPT_COUNTERMODE_UP;
179	  g_pwm.Init.Period = arr - 1;
180	  g_pwm.Init.RepetitionCounter = 0;
181	  if (HAL_GPT_PWM_Init(&g_pwm) != HAL_OK) {
182	    return -EIO;
183	  }
184	
185	  memset(&oc_cfg, 0, sizeof(oc_cfg));
186	  oc_cfg.OCMode = GPT_OCMODE_PWM1;
187	  oc_cfg.Pulse = 0;
188	  oc_cfg.OCPolarity = GPT_OCPOLARITY_HIGH;
189	  oc_cfg.OCNPolarity = GPT_OCNPOLARITY_LOW;
190	  oc_cfg.OCFastMode = GPT_OCFAST_DISABLE;
191	  oc_cfg.OCIdleState = GPT_OCIDLESTATE_RESET;
192	  oc_cfg.OCNIdleState = GPT_OCNIDLESTATE_RESET;
193	  if (HAL_GPT_PWM_ConfigChannel(&g_pwm, &oc_cfg, SOUND_PWM_CHANNEL) != HAL_OK) {
194	    return -EIO;
195	  }
196	
197	  g_pwm_running = false;
198	  g_pwm_ready = true;
199	  sound_pin_idle();
200	  return 0;
201	}
