220	static int sound_pwm_hz(uint16_t hz)
221	{
222	  uint32_t psc;
223	  uint32_t arr;
224	  uint32_t ccr;
225	
226	  if (sound_pwm_init_once() != 0) {
227	    return -EIO;
228	  }
229	
230	  if (sound_pwm_calc(hz, &psc, &arr, &ccr) != 0) {
231	    return -EIO;
232	  }
233	
234	  sound_pwm_mux();
235	  __HAL_GPT_DISABLE(&g_pwm);
236	  g_pwm.Instance->PSC = psc - 1;
237	  g_pwm.Instance->ARR = arr - 1;
238	  g_pwm.Instance->CCR1 = ccr;
239	  g_pwm.Instance->EGR = GPT_EGR_UG;
240	  if (HAL_GPT_PWM_Start(&g_pwm, SOUND_PWM_CHANNEL) != HAL_OK) {
241	    return -EIO;
242	  }
243	
244	  g_pwm_running = true;
245	  return 0;
246	}
