248	static void sound_tone(uint16_t hz, uint16_t ms)
249	{
250	  if (ms == 0) {
251	    return;
252	  }
253	
254	  if (hz == 0) {
255	    sound_pwm_silence();
256	    usleep((useconds_t)ms * 1000u);
257	    return;
258	  }
259	
260	  g_cur_hz = hz;
261	  g_cur_ms = ms;
262	  if (sound_pwm_hz(hz) != 0) {
263	    syslog(LOG_ERR, "sound: PWM %u Hz failed\n", (unsigned)hz);
264	    return;
265	  }
266	
267	  usleep((useconds_t)ms * 1000u);
268	  sound_pwm_silence();
269	}
