396	static void sound_post(myvendor_sound_id_t id)
397	{
398	  if (!g_started || id >= MYVENDOR_SOUND_COUNT) {
399	    return;
400	  }
401	
402	  pthread_mutex_lock(&g_lock);
403	  if (g_q_n >= SOUND_QUEUE_N) {
404	    pthread_mutex_unlock(&g_lock);
405	    return;
406	  }
407	
408	  g_q[g_q_tail] = id;
409	  g_q_tail = (uint8_t)((g_q_tail + 1u) % SOUND_QUEUE_N);
410	  g_q_n++;
411	  pthread_cond_signal(&g_cv);
412	  pthread_mutex_unlock(&g_lock);
413	}
