427	static void *sound_thread(void *arg)
428	{
429	  myvendor_sound_id_t id;
430	  sound_play_fn_t fn;
431	
432	  (void)arg;
433	  if (sound_pwm_init_once() != 0) {
434	    syslog(LOG_ERR, "sound: PWM init failed\n");
435	  }
436	
437	  for (;;) {
438	    pthread_mutex_lock(&g_lock);
439	    while (g_q_n == 0) {
440	      /* 队列空：挂起，不占 CPU，栈仍留在 BSS。 */
441	      pthread_cond_wait(&g_cv, &g_lock);
442	    }
443	
444	    id = g_q[g_q_head];
445	    g_q_head = (uint8_t)((g_q_head + 1u) % SOUND_QUEUE_N);
446	    g_q_n--;
447	    g_playing = true;
448	    g_cur_id = (uint8_t)id;
449	    pthread_mutex_unlock(&g_lock);
450	
451	    fn = (id < MYVENDOR_SOUND_COUNT) ? g_sound_play[id] : NULL;
452	    if (fn != NULL) {
453	      fn();
454	    }
455	
456	    pthread_mutex_lock(&g_lock);
457	    g_playing = false;
458	    pthread_mutex_unlock(&g_lock);
459	  }
460	
461	  return NULL;
462	}
