464	int myvendor_sound_start(void)
465	{
466	  pthread_attr_t attr;
467	  struct sched_param sp;
468	  pthread_t th;
469	  int ret;
470	
471	  if (g_started) {
472	    return 0;
473	  }
474	
475	  if (sound_pwm_init_once() != 0) {
476	    syslog(LOG_ERR, "sound: PWM init failed\n");
477	    return -EIO;
478	  }
479	  pthread_attr_init(&attr);
480	  ret = pthread_attr_setstack(&attr, g_sound_stack, sizeof(g_sound_stack));
481	  sp.sched_priority = SOUND_PRIO;
482	#ifdef PTHREAD_EXPLICIT_SCHED
483	  (void)pthread_attr_setinheritsched(&attr, PTHREAD_EXPLICIT_SCHED);
484	#endif
485	  (void)pthread_attr_setschedparam(&attr, &sp);
486	  if (ret == 0) {
487	    ret = pthread_create(&th, &attr, sound_thread, NULL);
488	  }
489	
490	  pthread_attr_destroy(&attr);
491	  if (ret != 0) {
492	    syslog(LOG_ERR, "sound: thread create failed %d\n", ret);
493	    return -ret;
494	  }
495	
496	#ifndef CONFIG_DISABLE_PTHREAD
497	  pthread_setname_np(th, "sound");
498	#endif
499	  pthread_detach(th);
500	  g_started = true;
501	  syslog(LOG_INFO, "sound: PA40 GPTIM2 CH1 PWM ready prio=%d\n", SOUND_PRIO);
502	  return 0;
503	}
