138	static bool diag_ble_ok(void)
139	{
140	#ifdef CONFIG_MYVENDOR_BLE_COMPANION_AUTOSTART
141	  if (board_ble_companion_busy())
142	    {
143	      return true;
144	    }
145	#endif
146	
147	#if defined(CONFIG_MYVENDOR_BLE_COMPANION) || defined(CONFIG_MYVENDOR_BICYCLE)
148	  if (!companion_bridge_thread_ok(DIAG_BLE_THREAD_MS))
149	    {
150	      diag_ble_log_unhealthy("thread");
151	      return false;
152	    }
153	#endif
154	
155	  if (sf32lb52_bt_hci_rx_stalled(DIAG_BLE_STALL_MS))
156	    {
157	      diag_ble_log_unhealthy("rxstall");
158	      return false;
159	    }
160	
161	  /** 控制器静默：命令确实发出去了，DIAG_BLE_CMD_MS 内一个事件都没回来。
162	   *
163	   *  与上面那条互补 —— `rx_stalled()` 只看**收包失败**（回调返回 <0），
164	   *  控制器彻底哑掉时一次都不失败（现场 `rxf=0`），所以那条看不见。
165	   *  2026-09-17 那次就是：562 s 之后 RX 全停，健康检查一路绿灯，直到
166	   *  605 s companion 心跳停掉才报 "thread"，中间 40 s 白等；再往后
167	   *  三个 L2CAP/命令缓冲池被抽干，多个线程卡在不可中断等待里，连
168	   *  三连杀都收不回来。这条能在 4 s 内把它拉起来复位。
169	   */
170	  if (sf32lb52_bt_hci_cmd_stalled(DIAG_BLE_CMD_MS))
171	    {
172	      /* **传感器链路占着射频时，命令沉默不算故障。**
173	       *
174	       * 现场：心率计一连上（我们=central），"开始广播"（`txop=0x200a`
175	       * = LE Set Advertising Enable）就被 LCPU 吞掉 —— 没有 Command Status、
176	       * 4.4 s 无任何 HCI 收发、`status=2`(NOT_READY)。以前这里一律判不健康 →
177	       * 复位 LCPU → **把心率计踢掉**（disconn 0x16）→ 8 s 后它连回来 → 再吞
178	       * 一次：自杀式循环。用户侧看到的就是"心率计活着时别的设备（含手机）
179	       * 搜不到板子；把心率计关机立刻就能搜到"。
180	       *
181	       * 所以：有传感器链路就记一行软告警放行，**不动适配器**；广播由
182	       * `g_ctx.adv_restart` 在链路空下来时自然接管。 */
183	      if (ble_sensor_connect_busy())
184	        {
185	          static bool deferred_logged;
186	
187	          if (!deferred_logged)
188	            {
189	              deferred_logged = true;
190	              syslog(LOG_WARNING,
191	                     "diag: ble cmd silent with sensor link up — "
192	                     "adv deferred, no adapter cycle\n");
193	            }
194	
195	          return true;
196	        }
197	
198	      diag_ble_log_unhealthy("cmdsilent");
199	      return false;
200	    }
201	
202	  /* 适配器不可用 / 正在被我们自己恢复时，"命令没回应"是必然结果，不是新故障。
203	   * 这时候再叠一次恢复，会让 `bt_disable_mc()` 撞上还没 init 完的
204	   * `hdev->conn_ctx` —— 2026-09-18 n005 现场就是 `bt_conn_ref(&NULL->acl_conns[0])`
205	   * （DACCVIOL mmfar=0x124），从 `bt_conn_cleanup_all()` 进来的，而触发它的
206	   * 正是"adapter cycle 跑到一半，diag 又叠了一次 LCPU 强制复位"。
207	   * 软告警放行，等这轮恢复自己跑完。 */
208	  if (companion_ble_recovering())
209	    {
210	      static bool recovering_logged;
211	
212	      if (!recovering_logged)
213	        {
214	          recovering_logged = true;
215	          syslog(LOG_WARNING,
216	                 "diag: ble cmd silent while adapter recovering — "
217	                 "no second recovery\n");
218	        }
219	
220	      return true;
221	    }
222	
223	  g_ble_soft = 0;
224	  return true;
225	}
