227	static int diag_ble_restart(void)
228	{
229	#ifdef CONFIG_MYVENDOR_BLE_COMPANION_AUTOSTART
230	  if (board_ble_companion_busy())
231	    {
232	      return 0;
233	    }
234	
235	  if (!board_ble_companion_pid_alive())
236	    {
237	      g_ble_soft = 0;
238	      syslog(LOG_ERR, "diag: ble companion thread respawn\n");
