243	#if defined(CONFIG_MYVENDOR_BLE_COMPANION) || defined(CONFIG_MYVENDOR_BICYCLE)
244	  /* 心跳已停：companion 堵在不可中断 HCI 等待上。只扳 LCPU 并清
245	   * skip_sync 会让它继续卡死，task_delete 也杀不掉，随后 skip respawn。 */
246	  if (!companion_bridge_thread_ok(DIAG_BLE_THREAD_MS))
247	    {
248	      g_ble_soft = 0;
249	      syslog(LOG_ERR, "diag: ble companion restart (thread stalled)\n");
250	#ifdef CONFIG_MYVENDOR_BLE_COMPANION_AUTOSTART
251	      return board_restart_ble_companion();
252	#else
253	      return sf32lb52_bt_controller_force_reset();
254	#endif
255	    }
256	
257	  if (g_ble_soft == 0)
258	    {
259	      g_ble_soft = 1;
260	      if (companion_bridge_alive_get())
261	        {
262	          syslog(LOG_WARNING, "diag: ble request companion adapter cycle\n");
263	          companion_bridge_diag_cycle_post();
264	          return 0;
265	        }
266	    }
267	#endif
268	
269	  /* 恢复中就别再叠一次：`bt_disable_mc()` 撞上还没 init 完的 conn_ctx 会
270	   * DACCVIOL（n005）。让这一轮跑完，diag 有 cooldown，之后还会再判。 */
271	  if (companion_ble_recovering())
272	    {
273	      static bool defer_logged;
274	
275	      if (!defer_logged)
276	        {
277	          defer_logged = true;
278	          syslog(LOG_WARNING,
279	                 "diag: ble restart deferred (adapter cycle in flight)\n");
280	        }
281	
282	      return 0;
283	    }
284	
285	  syslog(LOG_ERR, "diag: ble force LCPU reset\n");
286	  BLE_LOG("diag force LCPU skip=%d rxstall=%d",
287	          sf32lb52_bt_hci_skip_sync() ? 1 : 0,
288	          sf32lb52_bt_hci_rx_stalled(DIAG_BLE_STALL_MS) ? 1 : 0);
289	  return sf32lb52_bt_controller_force_reset();
290	}
