428	int myvendor_diag_register(const myvendor_diag_ops_t *ops)
429	{
430	  uint8_t i;
431	
432	  if (ops == NULL || ops->name == NULL || ops->ok == NULL ||
433	      ops->restart == NULL)
434	    {
435	      return -EINVAL;
436	    }
437	
438	  pthread_mutex_lock(&g_lock);
439	  for (i = 0; i < g_n; i++)
440	    {
441	      if (strcmp(g_slot[i].ops.name, ops->name) == 0)
442	        {
443	          g_slot[i].ops = *ops;
444	          pthread_mutex_unlock(&g_lock);
445	          return 0;
446	        }
447	    }
448	
449	  if (g_n >= DIAG_MAX)
450	    {
451	      pthread_mutex_unlock(&g_lock);
452	      return -ENOMEM;
453	    }
454	
455	  memset(&g_slot[g_n], 0, sizeof(g_slot[g_n]));
456	  g_slot[g_n].ops = *ops;
457	  g_n++;
458	  pthread_mutex_unlock(&g_lock);
459	  syslog(LOG_INFO, "diag: register %s fail=%u cooldown=%u\n",
460	         ops->name, (unsigned)ops->fail_ms, (unsigned)ops->cooldown_ms);
461	  return 0;
462	}
463	
464	static void diag_tick_one(struct diag_slot *s, uint32_t now)
465	{
466	  bool ok;
467	  uint32_t fail_ms;
468	  uint32_t cooldown;
469	
470	  if (s->ops.ok == NULL)
471	    {
472	      return;
473	    }
474	
475	  ok = s->ops.ok();
476	  if (ok)
477	    {
478	      s->fail_since_ms = 0;
479	      return;
480	    }
481	
482	  if (s->fail_since_ms == 0)
483	    {
484	      s->fail_since_ms = now;
485	      syslog(LOG_WARNING, "diag: %s unhealthy\n", s->ops.name);
486	      return;
487	    }
488	
489	  fail_ms = s->ops.fail_ms != 0 ? s->ops.fail_ms : 5000u;
490	  cooldown = s->ops.cooldown_ms != 0 ? s->ops.cooldown_ms : 15000u;
491	  if (diag_elapsed(now, s->fail_since_ms) < fail_ms)
492	    {
493	      return;
494	    }
495	
496	  if (s->last_restart_ms != 0 &&
497	      diag_elapsed(now, s->last_restart_ms) < cooldown)
498	    {
499	      return;
500	    }
501	
502	  syslog(LOG_ERR, "diag: %s restart (unhealthy %u ms, n=%u)\n",
503	         s->ops.name,
504	         (unsigned)diag_elapsed(now, s->fail_since_ms),
505	         (unsigned)(s->restarts + 1u));
506	  s->last_restart_ms = now;
507	  s->fail_since_ms = now;
508	  if (s->restarts < UINT16_MAX)
509	    {
510	      s->restarts++;
511	    }
512	
513	  if (s->ops.restart != NULL)
514	    {
515	      (void)s->ops.restart();
516	    }
517	}
518	
519	static void *diag_thread(void *arg)
520	{
521	  (void)arg;
522	  g_boot_ms = diag_now();
523	  syslog(LOG_INFO, "diag: thread up, grace %u ms\n",
524	         (unsigned)DIAG_GRACE_MS);
525	
526	  for (;;)
527	    {
528	      uint32_t now = diag_now();
529	      uint8_t i;
530	      uint8_t n;
531	
532	      if (diag_elapsed(now, g_boot_ms) >= DIAG_GRACE_MS)
533	        {
534	          pthread_mutex_lock(&g_lock);
535	          n = g_n;
536	          pthread_mutex_unlock(&g_lock);
537	          for (i = 0; i < n && i < DIAG_MAX; i++)
538	            {
539	              diag_tick_one(&g_slot[i], now);
540	            }
541	        }
542	
543	      myvendor_schedmon_tick();
544	
545	      /* 日志落盘：**节流**到 2 s 一次，或环内积压超过高水位时提前刷。
546	       *
547	       * 为什么不再每 tick 都刷：`myvendor_diaglog_flush()` 每次落盘都要在
548	       * `/mnt/kv`（SD 上的 LittleFS）上 open + write + close，而 SD 的块等待
549	       * 是 PIO **忙等**（见 chips/sf32lb52/sf32lb_sdio.c 的
550	       * `sd1_wait_write()` / `sd1_wait_card_idle()` / `sd1_wait_dat0()`），
551	       * 那段时间全部记在 diag 线程头上 —— 实测 diag 占 18.2% CPU 主要就是
552	       * 这条路径。2 s 一次把稳态 I/O 砍到 1/4；高水位那一路保证刷屏期不丢
553	       * （环只有 2 KB，等满 2 s 会溢出）。
554	       *
555	       * 位置刻意放在**主循环体**里、不在上面那个被 GRACE 门控的槽位遍历内 ——
556	       * 否则开机头 25 秒的日志不落盘，而开机那段正是 SD/LFS 挂载信息最密集、
557	       * 最值钱的地方。
558	       *
559	       * 也刻意**只在 diag 线程**刷：出错点那边（比如打完 SD 判死日志）往往正
560	       * 持着 g_sd_lock，在那里往文件系统写会自锁。 */
561	      {
562	        extern int myvendor_diaglog_flush(void);
563	        extern size_t myvendor_diaglog_pending(void);
564	
565	        if (g_flush_ms == 0 ||
566	            diag_elapsed(now, g_flush_ms) >= DIAGLOG_FLUSH_MS ||
567	            myvendor_diaglog_pending() >= DIAGLOG_FLUSH_HIWATER)
568	          {
569	            (void)myvendor_diaglog_flush();
570	            g_flush_ms = now;
571	          }
572	      }
573	
574	      usleep(DIAG_TICK_MS * 1000u);
575	    }
576	
577	  return NULL;
578	}
579	
580	int myvendor_diag_start(void)
581	{
582	  pthread_attr_t attr;
583	  struct sched_param sp;
584	  pthread_t th;
585	  int ret;
586	
587	  if (g_started)
588	    {
589	      return 0;
590	    }
591	
592	#ifdef CONFIG_BOARD_L96_GNSS
593	  (void)myvendor_diag_register(&g_gnss_ops);
594	#endif
595	#ifdef CONFIG_MYVENDOR_DVFS
596	  (void)myvendor_diag_register(&g_dvfs_ops);
597	#endif
598	#ifdef CONFIG_MTD
599	  (void)myvendor_diag_register(&g_fs_ops);
600	#endif
601	#ifdef CONFIG_BLUETOOTH
602	  (void)myvendor_diag_register(&g_ble_ops);
603	#endif
604	
605	  pthread_attr_init(&attr);
606	  ret = pthread_attr_setstack(&attr, g_diag_stack, sizeof(g_diag_stack));
607	  sp.sched_priority = DIAG_PRIORITY;
608	#ifdef PTHREAD_EXPLICIT_SCHED
609	  (void)pthread_attr_setinheritsched(&attr, PTHREAD_EXPLICIT_SCHED);
610	#endif
611	  (void)pthread_attr_setschedparam(&attr, &sp);
612	  if (ret == 0)
613	    {
614	      ret = pthread_create(&th, &attr, diag_thread, NULL);
615	    }
616	
617	  pthread_attr_destroy(&attr);
618	  if (ret != 0)
619	    {
620	      syslog(LOG_ERR, "diag: thread create failed %d\n", ret);
621	      return -ret;
622	    }
623	
624	#ifndef CONFIG_DISABLE_PTHREAD
625	  pthread_setname_np(th, "diag");
626	#endif
627	  pthread_detach(th);
628	  g_started = true;
629	  syslog(LOG_INFO, "diag: started prio=%d\n", DIAG_PRIORITY);
630	  return 0;
631	}
