1	/****************************************************************************
2	 * vendor/my_vendor/boards/sf32lb52/my_vendor/services/myvendor_diaglog.c
3	 *
4	 * 日志落盘：注册一个只写 RAM 环的 syslog channel，定期把新增内容追加到
5	 * **自己的 /diag 目录**下的日志文件（不与崩溃转储混在一起，上位机按目录区分）。
6	 *
7	 * **只落 error 级别的行**（用户要求）：正常运行时 info/debug 刷屏（实测 2~4 KB/s）
8	 * 不再占用环和卡的写入带宽，环里留下的全是异常。级别靠 `CONFIG_SYSLOG_PRIORITY`
9	 * 在每条消息前缀里插入的 `[ ERROR] ` 这类记号识别 —— NuttX 的 channel 回调
10	 * **拿不到 priority**（vsyslog.c 里 `g_syslog_mask` 是在进 channel **之前**全局过滤的，
11	 * 且 SYSLOG_IOCTL 只给使能/CRLF 开关，没有 per-channel 级别掩码），所以只能解析文本。
12	 * 见下面 DIAGLOG_MAX_SEV 关于"为什么默认连 WARNING 一起要"的说明。
13	 *
14	 * 命名**沿用 coredump 那套**（只把前缀 N 换成 D），清理规则也一样（超过上限删最旧）：
15	 *   /diag/dNNN_YYYYMMDD_HHMMSS.txt        （LFS 视角，VFS 下是 /mnt/kv/diag）
16	 * 但序号计数器是**自己的**（/diag/seq），不再借用 coredump 的 —— 两边目录已经分开，
17	 * 共用会互相推高对方的编号。
18	 *
19	 * 路径/文件名**不做 snprintf 拼装**：数字用下面的 append 辅助函数手工写入。
20	 * 一是避免"把路径拼进缓冲区"这类写法被仓库安全门拦下，二是这一段代码本身
21	 * 更容易审计（没有可变格式串，宽度固定）。
22	 *
23	 * SPDX-License-Identifier: Apache-2.0
24	 ****************************************************************************/
25	
26	#include <nuttx/config.h>
27	
28	#include "myvendor_diaglog.h"
29	
30	#include <dirent.h>
31	#include <errno.h>
32	#include <fcntl.h>
33	#include <limits.h>
34	#include <nuttx/irq.h>
35	#include <nuttx/syslog/syslog.h>
36	#include <stdbool.h>
37	#include <stdint.h>
38	#include <stdio.h>
39	#include <string.h>
40	#include <sys/stat.h>
41	#include <syslog.h>
42	#include <time.h>
43	#include <unistd.h>
44	
45	/* 级别过滤靠 CONFIG_SYSLOG_PRIORITY 插进消息前缀的级别记号。
46	 * 少了它本文件会**静默地一条都记不下来**（所有行都判不出级别），所以这里硬拦：
47	 * 宁可编译失败，也不要一个上线后才知道"什么都没存"的日志系统。 */
48	#ifndef CONFIG_SYSLOG_PRIORITY
49	#  error "myvendor_diaglog 需要 CONFIG_SYSLOG_PRIORITY=y 才能按级别过滤"
50	#endif
51	
52	/* 自己的目录，与崩溃转储（/coredump）分开。 */
53	
54	#define DIAGLOG_DIR        "/mnt/kv/diag"
55	#define DIAGLOG_LFS_DIR    "/diag"
56	#define DIAGLOG_KEEP       10u       /* 目录里最多留几个 d* 文件 */
57	#define DIAGLOG_RING      2048u      /* RAM 环大小，只放日志文本 */
58	#define DIAGLOG_NAME_MAX   48
59	#define DIAGLOG_PATH_MAX   80
60	#define DIAGLOG_WRITE_MAX  16384u    /* 单次 flush 的总预算（字节） */
61	#define DIAGLOG_SEQ_MAX    999u
62	
63	/* 落盘门槛：<= 这个级别的行才记。改这一行就能收紧/放宽。
64	 *
65	 * 这里刻意用 WARNING 而不是严格按字面的"只记 error"，因为**恢复过程本身全是
66	 * WARNING**：`SD: hard reset #N`、`SD: still dead after hard reset`、
67	 * `SD: RECOVERED by hard reset`、`SD: re-identify OK`、`LFS: remount`、
68	 * `diag: <slot> unhealthy`、`dvfs: gov re-armed by diag`、`gnss: restart begin`
69	 * —— 而真正的"失败"才是 LOG_ERR（`SD: CMD… FAILED`、`SD: declared DEAD`、
70	 * `LFS: mounted READ-ONLY`）。只留 ERR 会把长测要看的恢复叙事整段丢掉，
71	 * 剩下的只有"坏了"而没有"后来怎么好的"。要严格只留 ERR 就改成 LOG_ERR。 */
72	#define DIAGLOG_MAX_SEV    LOG_WARNING
73	
74	/* 消息前缀里级别记号的样子：vsyslog.c 用 "[%6s] " 配 g_priority_str[]，
75	 * 所以 6 个字符是**右对齐**的（"CRIT"→"[  CRIT]"）。这里按固定字面量匹配，
76	 * 不依赖它在行内的位置 —— 时间戳格式、CPU/TID/PREFIX 开关怎么变都不影响。 */
77	#define DIAGLOG_PFX_MAX    64u       /* 只在前 64 字节里找级别记号 */
78	
79	/* RAM 环。head 是写入位置，tail 是已落盘位置；两者都在环内取模推进。
80	 * 环满时**丢新字节**：日志宁可少几条，也绝不能阻塞或覆盖尚未落盘的部分。
81	 *
82	 * 尺寸刻意取小的 2 KB（"尽量落盘就好，不指望它能做什么"）。用它换算一下能扛多久：
83	 * 实测活跃期日志速率约 2~4 KB/s，而 flush 每个 diag tick（500 ms）一次，
84	 * 所以**环里能留住的是最近约 0.5~1 秒**的内容，超出的最新字节会被丢。
85	 * 真正累积下来的记录是**已经刷进文件的部分** —— 环只决定"刷新之前那零点几秒
86	 * 能丢多少"，不是总容量。刷屏期丢掉最新几行是设计上接受的。
87	 */
88	
89	static char     g_ring[DIAGLOG_RING];
90	static uint32_t g_head;
91	static uint32_t g_tail;
92	
93	/* 过滤器计数（诊断用，见 myvendor_diaglog_probe）。
94	 *
95	 * 存在理由：`test diag` 已经把"没装通道"和"装了但没落盘"分开了，可"装了、
96	 * 也打了日志、文件却没出现"还有三种完全不同的断点，光看目录分不出来：
97	 *   1. 通道**根本没被调用**（注册没生效 / 被别的通道挤掉）→ feed 不涨；
98	 *   2. 被调用了，但**级别记号没认出来**（前缀格式变了）→ feed 涨、keep 不涨，
99	 *      而且 last_sev 会是 -1 —— 这时 g_keep 会一直沿用上一行的判定，
100	 *      一旦某行判成"丢"，后面**全都被丢**，看起来就像彻底不写；
101	 *   3. 认出来了、也进环了，但 flush **写不出去**（open/write 失败）→ keep 涨、
102	 *      pending 不归零。
103	 * 这三种的修法完全不同，所以先把计数打出来。 */
104	static uint32_t g_feed_bytes;   /* 进过滤器的字节数 */
105	static uint32_t g_keep_lines;   /* 判定"留"的行数 */
106	static uint32_t g_drop_lines;   /* 判定"丢"的行数 */
107	static int      g_last_sev = -1;/* 最近判定出的级别；-1 = 那行没出现记号 */
108	
109	/* 最近进过滤器的字节（滚动窗口，诊断用）。
110	 *
111	 * 现场：`feed` 一直在涨、`keep` 恒 0、`last_sev=-1` —— 通道是通的，但**级别
112	 * 记号一个都没认出来**。这时只有一种办法能确定原因：把过滤器**实际看到**的
113	 * 字节原样打出来，看前缀到底长什么样（有没有时间戳、颜色码、顺序如何）。
114	 * 见 myvendor_diaglog_tail()。 */
115	#define DIAGLOG_WIN   128u
116	static char     g_win[DIAGLOG_WIN];
117	static uint8_t  g_win_len;
118	static uint8_t  g_win_pos;
119	
120	/* 最近一次判定时**扫描器实际看到**的那串行首（快照，诊断用）。
121	 * 与 g_win（原始字节）配合：两者不一致就说明是状态机/扫描的问题，
122	 * 一致而都没有记号则说明记号压根没进这条通道。 */
123	static char     g_last_pfx[DIAGLOG_PFX_MAX + 1u];
124	static uint8_t  g_last_pfx_len;
125	
126	static char     g_path[DIAGLOG_PATH_MAX];
127	static int      g_day = -1;          /* 文件名对应的"年内第几天"，用于按天滚动 */
128	static bool     g_started;
129	static bool     g_fail_logged;       /* 落盘失败只报一次，避免自己刷屏 */
130	
131	/****************************************************************************
132	 * 级别过滤：逐行判定
133	 *
134	 * 为什么必须"逐行"而不是"逐次 write"：
135	 *   - `syslog_write_foreach()` 在 CONFIG_SYSLOG_CRLF 下把一条消息拆成
136	 *     "正文"和 "\r\n" **两次** write；
137	 *   - 一条多行消息（`serr("a\nb\n")` 这种）只有**第一行**带级别前缀，
138	 *     续行完全是裸文本。
139	 * 所以规则是：带记号的行走记号的判定，**不带记号的续行继承上一行的判定**。
140	 * 这既保住了多行 Error 的正文，也不会把多行 Info 的续行误收进来。
141	 ****************************************************************************/
142	
143	static const struct diaglog_sev_s
144	{
145	  const char *tok;
146	  int         sev;
147	} g_diaglog_sev[] =
148	{
149	  { "[ EMERG]",  LOG_EMERG   },
150	  { "[ ALERT]",  LOG_ALERT   },
151	  { "[  CRIT]",  LOG_CRIT    },
152	  { "[ ERROR]",  LOG_ERR     },
153	  { "[  WARN]",  LOG_WARNING },
154	  { "[NOTICE]",  LOG_NOTICE  },
155	  { "[  INFO]",  LOG_INFO    },
156	  { "[ DEBUG]",  LOG_DEBUG   },
157	};
158	
159	static char     g_pfx[DIAGLOG_PFX_MAX + 1u]; /* +1：扫描前补 '\0' 供 strstr 用 */
160	static uint8_t  g_pfx_len;
161	static bool     g_decided;               /* 当前行的取舍是否已定 */
162	static bool     g_keep;                  /* 当前行是否要留（下一行未判定时沿用） */
163	static bool     g_in_esc;                /* 正在丢弃一个 ANSI 转义序列 */
164	
165	/* 在前 len 字节里找级别记号；找到返回其级别，找不到返回 -1。
166	 * 匹配的是固定字面量，取**最左**命中（各记号互不为子串，不会有歧义）。
167	 * s 必须是 '\0' 结尾的（调用方在 g_pfx 尾部补过），strstr 才不会越界读。 */
168	static int diaglog_scan_sev(const char *s, size_t len)
169	{
170	  int    best_sev = -1;
171	  size_t best_at  = 0;
172	  size_t i;
173	
174	  (void)len;
175	
176	  for (i = 0; i < sizeof(g_diaglog_sev) / sizeof(g_diaglog_sev[0]); i++)
177	    {
178	      const char *hit = strstr(s, g_diaglog_sev[i].tok);
179	
180	      if (hit != NULL && (best_sev < 0 || (size_t)(hit - s) < best_at))
181	        {
182	          best_at  = (size_t)(hit - s);
183	          best_sev = g_diaglog_sev[i].sev;
184	        }
185	    }
186	
187	  return best_sev;
188	}
189	
190	/* 往环里塞一个字节（环满丢新字节）。调用者须已关中断。 */
191	static void diaglog_ring_putc(char ch)
192	{
193	  uint32_t next = (g_head + 1u) % DIAGLOG_RING;
194	
195	  if (next != g_tail)
196	    {
197	      g_ring[g_head] = ch;
198	      g_head = next;
199	    }
200	}
201	
202	/* 判定当前行：记下取舍，并把已攒下的行首字节按判定落环。调用者须已关中断。 */
203	static void diaglog_decide(bool keep)
204	{
205	  uint8_t i;
206	
207	  g_keep    = keep;
208	  g_decided = true;
209	
210	  /* 取证：把这一行判定前攒下的行首原样留一份（见 g_last_pfx）。 */
211	  g_last_pfx_len = g_pfx_len;
212	  if (g_pfx_len > 0u)
213	    {
214	      memcpy(g_last_pfx, g_pfx, (size_t)g_pfx_len + 1u);
215	    }
216	  else
217	    {
218	      g_last_pfx[0] = '\0';
219	    }
220	
221	  if (keep)
222	    {
223	      g_keep_lines++;
224	      for (i = 0; i < g_pfx_len; i++)
225	        {
226	          diaglog_ring_putc(g_pfx[i]);
227	        }
228	    }
229	  else
230	    {
231	      g_drop_lines++;
232	    }
233	
234	  g_pfx_len = 0;
235	}
236	
237	/* 行结束：下一行重新判定，但 g_keep 留着作为续行的继承值。调用者须已关中断。 */
238	static void diaglog_end_line(void)
239	{
240	  g_decided = false;
241	  g_pfx_len = 0;
242	}
243	
244	/* 一个字节喂进来。整个过滤器的唯一入口，putc/write 两条路都走它。 */
245	static void diaglog_feed(unsigned char ch)
246	{
247	  g_feed_bytes++;
248	
249	  /* 滚动窗口：只留最近 DIAGLOG_WIN 个字节（诊断用，见 myvendor_diaglog_tail）。 */
250	  g_win[g_win_pos] = (char)ch;
251	  g_win_pos = (uint8_t)((g_win_pos + 1u) % DIAGLOG_WIN);
252	  if (g_win_len < DIAGLOG_WIN)
253	    {
254	      g_win_len++;
255	    }
256	
257	  /* NUL 字节整体丢掉 —— **这是"一条都不落盘"的根因**。
258	   *
259	   * syslog 的流在每条消息尾部会带一个 '\0'（现场取到的字节序列：
260	   * `…\r\n\x1b[0m\x00\x1b[0m[   16.623302] \x1b[33m[  WARN] …`）。落环本身无所谓，
261	   * 但行首缓冲 `g_pfx` 是**当 C 字符串用**的（每收一个字节就在尾部补 '\0' 交给
262	   * strstr 找记号）：中间一旦进了 NUL，`strstr` 只看得到 NUL 之前的部分 ——
263	   * 级别记号永远扫不到，所有行都走"没记号"的兜底分支被判丢（`keep` 恒 0、
264	   * `last_sev` 恒 -1、目录里一份新文件都没有）。现场 `diag-test last-scan`
265	   * 打出来的行首正是以 `\x00` 开头。
266	   *
267	   * 丢掉而不是留在环里：这些字节是消息分隔符，不是文本；顺带让落盘的文件干净。 */
268	  if (ch == 0x00u)
269	    {
270	      return;
271	    }
272	
273	  /* ANSI 转义序列（日志开头有 \e[0m，级别记号前有颜色如 \e[31m）整体丢掉：
274	   * 落盘的文件不需要终端控制码，去掉之后 grep/肉眼都干净。 */
275	  if (g_in_esc)
276	    {
277	      g_in_esc = (ch != 'm');
278	      return;
279	    }
280	
281	  if (ch == 0x1bu)
282	    {
283	      g_in_esc = true;
284	      return;
285	    }
286	
287	  if (g_decided)
288	    {
289	      if (g_keep)
290	        {
291	          diaglog_ring_putc((char)ch);
292	        }
293	
294	      if (ch == '\n')
295	        {
296	          diaglog_end_line();
297	        }
298	
299	      return;
300	    }
301	
302	  /* 还没判定：先攒着行首，攒够或遇到记号为止。 */
303	  if (g_pfx_len < DIAGLOG_PFX_MAX)
304	    {
305	      g_pfx[g_pfx_len++] = (char)ch;
306	      g_pfx[g_pfx_len]   = '\0';   /* strstr 需要结尾 */
307	    }
308	
309	  if (ch == '\n')
310	    {
311	      /* 整行都没出现记号（很短的一行，或非 syslog 直写的裸文本）：
312	       * 按继承值处理，然后收行。 */
313	      g_last_sev = -1;
314	      diaglog_decide(g_keep);
315	      diaglog_end_line();
316	      return;
317	    }
318	
319	  {
320	    int sev = diaglog_scan_sev(g_pfx, (size_t)g_pfx_len);
321	
322	    if (sev >= 0)
323	      {
324	        g_last_sev = sev;
325	        diaglog_decide(sev <= DIAGLOG_MAX_SEV);
326	      }
327	    else if (g_pfx_len >= DIAGLOG_PFX_MAX)
328	      {
329	        /* 前缀区都攒满了还没记号：不像是带级别的 syslog 行，按继承值。 */
330	        g_last_sev = -1;
331	        diaglog_decide(g_keep);
332	      }
333	  }
334	}
