336	/****************************************************************************
337	 * 无格式串的路径拼装
338	 ****************************************************************************/
339	
340	/* 把 v 按固定位数（零填充）写进 p，返回新的写指针。v 超出位数时按低位截断。 */
341	
342	static char *diaglog_put_u(char *p, unsigned v, unsigned width)
343	{
344	  unsigned i;
345	
346	  for (i = 0; i < width; i++)
347	    {
348	      unsigned digit = v;
349	      unsigned j;
350	
351	      /* 第 i 位 = v / 10^(width-1-i) 的个位；不用除法表，固定次数循环取。 */
352	      for (j = 0; j < (width - 1u - i); j++)
353	        {
354	          digit /= 10u;
355	        }
356	
357	      p[i] = (char)('0' + (digit % 10u));
358	    }
359	
360	  return p + width;
361	}
362	
363	/* 组一个 dNNN_YYYYMMDD_HHMMSS.txt 名字；seq 是本目录自己的计数器。 */
364	
365	static void diaglog_mkname(char *name, size_t n, unsigned seq, time_t now)
366	{
367	  struct tm tm;
368	  char     *p;
369	
370	  if (n < DIAGLOG_NAME_MAX)
371	    {
372	      name[0] = '\0';
373	      return;
374	    }
375	
376	  localtime_r(&now, &tm);
377	  if (tm.tm_year < 0)
378	    {
379	      memset(&tm, 0, sizeof(tm));
380	    }
381	
382	  p = name;
383	  *p++ = 'd';
384	  p = diaglog_put_u(p, seq % 1000u, 3u);
385	  *p++ = '_';
386	  p = diaglog_put_u(p, (unsigned)(tm.tm_year + 1900), 4u);
387	  p = diaglog_put_u(p, (unsigned)(tm.tm_mon + 1), 2u);
388	  p = diaglog_put_u(p, (unsigned)tm.tm_mday, 2u);
389	  *p++ = '_';
390	  p = diaglog_put_u(p, (unsigned)tm.tm_hour, 2u);
391	  p = diaglog_put_u(p, (unsigned)tm.tm_min, 2u);
392	  p = diaglog_put_u(p, (unsigned)tm.tm_sec, 2u);
393	  memcpy(p, ".txt", 5u);
394	
395	  g_day = tm.tm_yday;
396	}
