398	/* 目录 + '/' + 名字。 */
399	
400	static void diaglog_mkpath(char *path, size_t n, const char *name)
401	{
402	  size_t d = strlen(DIAGLOG_DIR);
403	
404	  if (d + 1u + strlen(name) + 1u > n)
405	    {
406	      path[0] = '\0';
407	      return;
408	    }
409	
410	  memcpy(path, DIAGLOG_DIR, d);
411	  path[d] = '/';
412	  memcpy(path + d + 1u, name, strlen(name) + 1u);
413	}
