415	/* 从 dNNN_YYYYMMDD_HHMMSS.txt 里取日历戳（形状同 coredump 的 nNNN_...，只换前缀）。
416	 * 无 sscanf：手工解析固定宽度。
417	 *
418	 * 索引要按实际布局数：'d' + NNN + '_' 占 0..4，所以年月日时分秒从 5 开始 ——
419	 * 5..8 / 9..10 / 11..12 / 13='_' / 14..15 / 16..17 / 18..19，20..23 是 ".txt"。
420	 * 早先这里按 4 起算，把 '_' 当数字读，于是**每个**文件都解析失败、清理永不触发
421	 * （"最多 10 条"形同虚设）。降级名 dNNN.txt 记为 0（最老），规则同 coredump。 */
422	
423	static bool diaglog_name_stamp(const char *name, long *stamp)
424	{
425	  static const unsigned pos[6] = { 5u, 9u, 11u, 14u, 16u, 18u }; /* yyyy mm dd hh mm ss */
426	  static const unsigned wid[6] = { 4u, 2u, 2u, 2u, 2u, 2u };
427	  size_t                len;
428	  unsigned              i;
429	  long                  v = 0;
430	
431	  if (name == NULL || name[0] != 'd')
432	    {
433	      return false;
434	    }
435	
436	  len = strlen(name);
437	  if (len < 8u || memcmp(name + len - 4u, ".txt", 4u) != 0)
438	    {
439	      return false;
440	    }
441	
442	  if (len < 24u)
443	    {
444	      *stamp = 0;                /* dNNN.txt —— 没有日历戳，当最老 */
445	      return true;
446	    }
447	
448	  for (i = 0; i < 6u; i++)
449	    {
450	      unsigned j;
451	      long     acc = 0;
452	
453	      for (j = 0; j < wid[i]; j++)
454	        {
455	          char c = name[pos[i] + j];
456	
457	          if (c < '0' || c > '9')
458	            {
459	              return false;
460	            }
461	
462	          acc = acc * 10L + (long)(c - '0');
463	        }
464	
465	      v = v * 10000L + acc;
466	    }
467	
468	  *stamp = v;
469	  return true;
470	}
