472	/****************************************************************************
473	 * syslog channel：只搬字节进 RAM 环
474	 ****************************************************************************/
475	
476	static int diaglog_putc(FAR syslog_channel_t *channel, int ch)
477	{
478	  irqstate_t flags;
479	
480	  (void)channel;
481	
482	  flags = up_irq_save();
483	  diaglog_feed((unsigned char)ch);
484	  up_irq_restore(flags);
485	  return ch;
486	}
487	
488	static ssize_t diaglog_write(FAR syslog_channel_t *channel,
489	                             FAR const char *buf, size_t len)
490	{
491	  irqstate_t flags;
492	  size_t     i;
493	
494	  (void)channel;
495	
496	  if (buf == NULL || len == 0)
497	    {
498	      return 0;
499	    }
500	
501	  /* 整块在一个关中断区里过过滤器：状态机（行首缓冲、判定、转义中）是全局的，
502	   * 拆开处理会让别的上下文插进来把行切乱。
503	   * 代价是关中断时间与 len 成正比，但这里一次最多一条 syslog 行（几十~几百字节，
504	   * 240 MHz 下是微秒级），且**不关中断也不碰任何存储** —— 与"注册一个会阻塞在
505	   * SD 卡上的文件通道"是根本不同的量级。 */
506	  flags = up_irq_save();
507	  for (i = 0; i < len; i++)
508	    {
509	      diaglog_feed((unsigned char)buf[i]);
510	    }
511	
512	  up_irq_restore(flags);
513	  return (ssize_t)len;
514	}
515	
516	/* sc_flush 由 NuttX 在崩溃路径上调。这里**刻意什么都不做**：RAM 环没有
517	 * "缓冲待刷"的概念，而在 panic 上下文里去走文件系统是危险的。真正的崩溃落盘
518	 * 交给 coredump 那条已验证的裸 LittleFS 路径，它通过
519	 * myvendor_diaglog_snapshot() 取环内容一起写出去。 */
520	
521	static int diaglog_noop_flush(FAR syslog_channel_t *channel)
522	{
523	  (void)channel;
524	  return 0;
525	}
