527	static const struct syslog_channel_ops_s g_diaglog_ops =
528	{
529	  .sc_putc        = diaglog_putc,
530	  .sc_flush       = diaglog_noop_flush,
531	  .sc_write       = diaglog_write,
532	  .sc_write_force = diaglog_write,   /* 中断上下文走同一条：只搬 RAM */
533	};
