540	/****************************************************************************
541	 * 清理：只处理 d* 文件，超过 DIAGLOG_KEEP 删最旧（形状同 coredump）
542	 ****************************************************************************/
543	
544	static bool diaglog_drop_oldest(void)
545	{
546	  DIR           *dir;
547	  struct dirent *de;
548	  char           oldest[DIAGLOG_NAME_MAX];
549	  long           oldest_stamp = LONG_MAX;
550	  bool           have = false;
551	
552	  dir = opendir(DIAGLOG_DIR);
553	  if (dir == NULL)
554	    {
555	      return false;
556	    }
557	
558	  oldest[0] = '\0';
559	  while ((de = readdir(dir)) != NULL)
560	    {
561	      long stamp;
562	
563	      if (de->d_name[0] != 'd' || !diaglog_name_stamp(de->d_name, &stamp))
564	        {
565	          continue;
566	        }
567	
568	      /* 哨兵用 LONG_MAX 而不是 0：降级名 dNNN.txt 的戳就是 0，
569	       * 用 0 当初值会让"还没遇到任何文件"和"遇到最老文件"混淆。 */
570	      if (!have || stamp < oldest_stamp ||
571	          (stamp == oldest_stamp && strcmp(de->d_name, oldest) < 0))
572	        {
573	          have = true;
574	          oldest_stamp = stamp;
575	          memcpy(oldest, de->d_name, sizeof(oldest) - 1u);
576	          oldest[sizeof(oldest) - 1u] = '\0';
577	        }
578	    }
579	
580	  closedir(dir);
581	
582	  if (oldest[0] == '\0')
583	    {
584	      return false;
585	    }
586	
587	  {
588	    char path[DIAGLOG_PATH_MAX];
589	
590	    diaglog_mkpath(path, sizeof(path), oldest);
591	    if (path[0] == '\0')
592	      {
593	        return false;
594	      }
595	
596	    return (unlink(path) == 0);
597	  }
598	}
599	
600	static void diaglog_prune(void)
601	{
602	  unsigned      count = 0;
603	  DIR          *dir;
604	  struct dirent *de;
605	
606	  dir = opendir(DIAGLOG_DIR);
607	  if (dir == NULL)
608	    {
609	      return;
610	    }
611	
612	  while ((de = readdir(dir)) != NULL)
613	    {
614	      long stamp;
615	
616	      if (de->d_name[0] == 'd' && diaglog_name_stamp(de->d_name, &stamp))
617	        {
618	          count++;
619	        }
620	    }
621	
622	  closedir(dir);
623	
624	  while (count > DIAGLOG_KEEP)
625	    {
626	      if (!diaglog_drop_oldest())
627	        {
628	          break;
629	        }
630	
631	      count--;
632	    }
633	}
