635	/****************************************************************************
636	 * seq：一个序号文件记"开机第几次日志"（本目录自己的，与 coredump 的 seq 无关）
637	 ****************************************************************************/
638	
639	static unsigned diaglog_next_seq(void)
640	{
641	  const char *seq_path = DIAGLOG_DIR "/seq";
642	  char        buf[16];
643	  int         fd;
644	  ssize_t     n;
645	  unsigned    v = 0;
646	  unsigned    i;
647	
648	  fd = open(seq_path, O_RDONLY);
649	  if (fd >= 0)
650	    {
651	      n = read(fd, buf, sizeof(buf) - 1u);
652	      close(fd);
653	      if (n > 0)
654	        {
655	          buf[n] = '\0';
656	          for (i = 0; i < (unsigned)n && buf[i] >= '0' && buf[i] <= '9'; i++)
657	            {
658	              v = v * 10u + (unsigned)(buf[i] - '0');
659	            }
660	        }
661	    }
662	
663	  v = (v + 1u) % (DIAGLOG_SEQ_MAX + 1u);
664	
665	  {
666	    char *p;
667	
668	    p = diaglog_put_u(buf, v, 3u);
669	    *p++ = '\n';
670	
671	    fd = open(seq_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
672	    if (fd >= 0)
673	      {
674	        (void)write(fd, buf, (size_t)(p - buf));
675	        close(fd);
676	      }
677	  }
678	
679	  return v;
680	}
