685	
686	int myvendor_diaglog_start(void)
687	{
688	  unsigned seq;
689	  time_t   now = time(NULL);
690	  char     name[DIAGLOG_NAME_MAX];
691	  int      ret;
692	
693	  if (g_started)
694	    {
695	      return 0;
696	    }
697	
698	  /* 目录现在是自己独占的，没有别人会先建它 —— 这里必须真的建出来。 */
699	  ret = mkdir(DIAGLOG_DIR, 0755);
700	  if (ret < 0 && errno != EEXIST)
701	    {
702	      return -errno;
703	    }
704	
705	  seq = diaglog_next_seq();
706	  diaglog_mkname(name, sizeof(name), seq, now);
707	  diaglog_mkpath(g_path, sizeof(g_path), name);
708	  if (g_path[0] == '\0')
709	    {
710	      return -ENAMETOOLONG;
711	    }
712	
713	  diaglog_prune();
714	
715	  ret = syslog_channel_register(&g_diaglog_channel);
716	  if (ret < 0)
717	    {
718	      return ret;
719	    }
720	
721	  g_started = true;
722	
723	  /* 这一行本身也会进环，正好验证通道已经生效。 */
724	  syslog(LOG_INFO, "diaglog: ring %u B seq=%u keep %u\n",
725	         (unsigned)DIAGLOG_RING, seq, (unsigned)DIAGLOG_KEEP);
726	  return 0;
727	}
