729	bool myvendor_diaglog_started(void)
730	{
731	  return g_started;
732	}
733	
734	int myvendor_diaglog_flush(void)
735	{
736	  irqstate_t flags;
737	  uint32_t   head;
738	  uint32_t   tail;
739	  int        fd;
740	
741	  if (!g_started)
742	    {
743	      /* **自愈**：启动只在上电时试一次，而那一刻可能正好撞上 /mnt/kv 还没挂好
744	       * 或 SD 哑着（现场就有 SD mute → re-identify 的窗口）。原来一次失败就
745	       * 整轮开机静默不写日志 —— 而失败信息又走 `serr()`（本构建编译为空），
746	       * 于是完全不可观测。这里按调用次数节流重试（diag 线程 500 ms 一次 ⇒
747	       * 每 20 次 ≈ 10 s），不用任何时基，代价可忽略。 */
748	      static unsigned retry_n;
749	
750	      if (retry_n == 0u || retry_n >= 20u)
751	        {
752	          int rc;
753	
754	          retry_n = 0u;
755	          rc = myvendor_diaglog_start();
756	          if (rc == 0)
757	            {
758	              syslog(LOG_WARNING, "diaglog: late start ok (retried)\n");
759	            }
760	          else
761	            {
762	              syslog(LOG_WARNING, "diaglog: start retry failed rc=%d\n", rc);
763	            }
764	        }
765	
766	      retry_n++;
767	
768	      if (!g_started)
769	        {
770	          return -EAGAIN;
771	        }
772	    }
773	
774	  /* 按天滚动：跨天后换一个文件（同一次开机也就有了"一天一个"）。 */
775	  {
776	    time_t    now = time(NULL);
777	    struct tm tm;
778	
779	    localtime_r(&now, &tm);
780	    if (tm.tm_yday != g_day)
781	      {
782	        char name[DIAGLOG_NAME_MAX];
783	
784	        diaglog_mkname(name, sizeof(name), diaglog_next_seq(), now);
785	        diaglog_mkpath(g_path, sizeof(g_path), name);
786	        diaglog_prune();
787	      }
788	  }
789	
790	  flags = up_irq_save();
791	  head = g_head;
792	  tail = g_tail;
793	  up_irq_restore(flags);
794	
795	  if (head == tail)
796	    {
797	      return 0;
798	    }
799	
800	  fd = open(g_path, O_WRONLY | O_CREAT | O_APPEND, 0644);
801	  if (fd < 0)
802	    {
803	      int err = errno;
804	
805	      /* 写不了就保留在环里，下次再试；绝不因为日志失败去格式化或复位。
806	       * 首次失败报一行（之后静默）—— 否则"完全没落盘"会无声无息，
807	       * 那正是这套东西要解决的毛病。errno 先存下来，syslog 会改它。 */
808	      if (!g_fail_logged)
809	        {
810	          g_fail_logged = true;
811	          syslog(LOG_ERR, "diaglog: flush open failed %d, keep in ring\n", err);
812	        }
813	
814	      return -err;
815	    }
816	
817	  /* 一直写到环空为止，但受 DIAGLOG_WRITE_MAX 总预算约束。
818	   *
819	   * 早先的版本每个 tick 只写 2048 B（约 400 B/s），而实测活跃期日志速率是
820	   * 2~4 KB/s —— 入不敷出，环会长期满着、持续丢最新几行。现在按预算尽量写到空：
821	   * 正常速率下环几乎总是空的（内容基本立刻落盘），只有刷屏期才会丢，
822	   * 这也正是"尽量落盘、大量异常就算了"的语义。
823	   *
824	   * 每轮重新取 head，才能把本轮写入期间新产生的日志也一起带走。 */
825	
826	  {
827	    int total = 0;
828	
829	    while (total < (int)DIAGLOG_WRITE_MAX)
830	      {
831	        uint32_t n;
832	        ssize_t  nw;
833	
834	        flags = up_irq_save();
835	        head = g_head;
836	        tail = g_tail;
837	        up_irq_restore(flags);
838	
839	        if (head == tail)
840	          {
841	            break;
842	          }
843	
844	        n = (head > tail) ? (head - tail) : (DIAGLOG_RING - tail);
845	        if (n > (uint32_t)((int)DIAGLOG_WRITE_MAX - total))
846	          {
847	            n = (uint32_t)((int)DIAGLOG_WRITE_MAX - total);
848	          }
849	
850	        nw = write(fd, &g_ring[tail], n);
851	        if (nw <= 0)
852	          {
853	            if (total == 0)
854	              {
855	                close(fd);
856	                return (nw == 0) ? 0 : -errno;
857	              }
858	
859	            break;
860	          }
861	
862	        flags = up_irq_save();
863	        g_tail = (g_tail + (uint32_t)nw) % DIAGLOG_RING;
864	        up_irq_restore(flags);
865	        total += (int)nw;
866	      }
867	
868	    close(fd);
869	    return total;
870	  }
871	}
