940	/* 把非可打印字节转义成 \n / \r / \t / \xNN，便于在日志里一眼辨认。 */
941	static size_t diaglog_escape(const char *src, size_t len, char *out, size_t n)
942	{
943	  static const char hex[] = "0123456789abcdef";
944	  size_t o = 0;
945	  size_t i;
946	
947	  if (out == NULL || n < 2u)
948	    {
949	      return 0;
950	    }
951	
952	  for (i = 0; i < len && o + 4u < n; i++)
953	    {
954	      unsigned char c = (unsigned char)src[i];
955	
956	      if (c == '\n')
957	        {
958	          out[o++] = '\\';
959	          out[o++] = 'n';
960	        }
961	      else if (c == '\r')
962	        {
963	          out[o++] = '\\';
964	          out[o++] = 'r';
965	        }
966	      else if (c == '\t')
967	        {
968	          out[o++] = '\\';
969	          out[o++] = 't';
970	        }
971	      else if (c < 0x20u || c > 0x7eu)
972	        {
973	          out[o++] = '\\';
974	          out[o++] = 'x';
975	          out[o++] = hex[(c >> 4) & 0x0fu];
976	          out[o++] = hex[c & 0x0fu];
977	        }
978	      else
979	        {
980	          out[o++] = (char)c;
981	        }
982	    }
983	
984	  out[o] = '\0';
985	  return o;
986	}
987	
988	size_t myvendor_diaglog_tail(char *out, size_t n)
989	{
990	  char       tmp[DIAGLOG_WIN];
991	  irqstate_t flags;
992	  uint8_t    len;
993	  uint8_t    start;
994	  unsigned   i;
995	
996	  if (out == NULL || n < 2u)
997	    {
998	      return 0;
999	    }
1000	
1001	  flags = up_irq_save();
1002	  len   = g_win_len;
1003	  start = (uint8_t)((g_win_pos + DIAGLOG_WIN - len) % DIAGLOG_WIN);
1004	  for (i = 0; i < len; i++)
