1036	size_t myvendor_diaglog_snapshot(char *out, size_t n)
1037	{
1038	  uint32_t head;
1039	  uint32_t tail;
1040	  size_t   used = 0;
1041	
1042	  if (out == NULL || n < 2u)
1043	    {
1044	      return 0;
1045	    }
1046	
1047	  head = g_head;
1048	  tail = g_tail;
1049	  if (head == tail)
1050	    {
1051	      out[0] = '\0';
1052	      return 0;
1053	    }
1054	
1055	  /* 从 tail 到 head，按时间顺序拷出来。只做内存拷贝，可以在很差的环境里调用。 */
1056	  while (tail != head && used + 1u < n)
1057	    {
1058	      out[used++] = g_ring[tail];
1059	      tail = (tail + 1u) % DIAGLOG_RING;
1060	    }
1061	
1062	  out[used] = '\0';
1063	  return used;
1064	}
