178	/** @brief ioctl LCDDEVIO_PUTAREA 提交一条带。 */
179	static int myvendor_lcd_putarea_locked(const struct myvendor_lcd_flush_job_s *job)
180	{
181	  struct lcddev_area_s lcd_area;
182	  size_t rows;
183	  size_t nbytes;
184	
185	  if (g_lcd_disp.lcd_fd < 0 || job == NULL || !job->valid)
186	    {
187	      return -EINVAL;
