189	
190	  rows = (size_t)(job->area.y2 - job->area.y1 + 1);
191	  nbytes = rows * (size_t)job->stride;
192	
193	  lcd_area.row_start = job->area.y1;
194	  lcd_area.row_end   = job->area.y2;
195	  lcd_area.col_start = job->area.x1;
196	  lcd_area.col_end   = job->area.x2;
197	  lcd_area.stride    = (fb_coord_t)job->stride;
198	  lcd_area.data      = (uint8_t *)job->data;
199	
200	  myvendor_lcd_dcache_clean(job->data, nbytes);
201	
202	  return ioctl(g_lcd_disp.lcd_fd, LCDDEVIO_PUTAREA,
203	               (unsigned long)(uintptr_t)&lcd_area);
