319	/** @brief 两 timespec 间毫秒差。 */
320	static uint32_t myvendor_lcd_elapsed_ms(const struct timespec *t0,
321	    const struct timespec *t1)
322	{
323	  time_t sec = t1->tv_sec - t0->tv_sec;
324	  long nsec = t1->tv_nsec - t0->tv_nsec;
325	
326	  if (nsec < 0)
327	    {
328	      sec--;
329	      nsec += 1000000000L;
330	    }
331	
332	  if (sec < 0)
333	    {
334	      return 0;
335	    }
336	
337	  return (uint32_t)((uint64_t)sec * 1000u + (uint64_t)nsec / 1000000u);
338	}
339	
340	/** @brief timespec 加毫秒。 */
341	static void myvendor_lcd_timespec_add_ms(struct timespec *ts, uint32_t ms)
342	{
343	  ts->tv_sec  += (time_t)(ms / 1000u);
344	  ts->tv_nsec += (long)(ms % 1000u) * 1000000L;
345	  if (ts->tv_nsec >= 1000000000L)
346	    {
347	      ts->tv_sec++;
348	      ts->tv_nsec -= 1000000000L;
349	    }
350	}
