355	/** @brief 持锁等待 job/worker 空闲。 */
356	static bool myvendor_lcd_wait_idle_locked(uint32_t max_ms,
357	    uint32_t * waited_ms_out)
358	{
359	  struct timespec t0;
360	  struct timespec now;
361	
362	  clock_gettime(CLOCK_REALTIME, &t0);
363	
364	  while (lcd_disp_is_busy_locked())
365	    {
366	      if (max_ms == 0)
367	        {
368	          pthread_cond_wait(&g_lcd_disp.idle_cond, &g_lcd_disp.lock);
369	          continue;
370	        }
371	
372	      clock_gettime(CLOCK_REALTIME, &now);
373	      {
374	        uint32_t elapsed = myvendor_lcd_elapsed_ms(&t0, &now);
375	
376	        if (elapsed >= max_ms)
377	          {
378	            if (waited_ms_out != NULL)
379	              {
380	                *waited_ms_out = elapsed;
381	              }
382	
383	            return !lcd_disp_is_busy_locked();
384	          }
385	
386	        myvendor_lcd_timespec_add_ms(&now, max_ms - elapsed);
387	      }
388	
389	      if (pthread_cond_timedwait(&g_lcd_disp.idle_cond, &g_lcd_disp.lock,
390	              &now) == ETIMEDOUT)
391	        {
392	          if (waited_ms_out != NULL)
393	            {
394	              clock_gettime(CLOCK_REALTIME, &now);
395	              *waited_ms_out = myvendor_lcd_elapsed_ms(&t0, &now);
396	            }
397	
398	          return !lcd_disp_is_busy_locked();
399	        }
400	    }
401	
402	  if (waited_ms_out != NULL)
403	    {
404	      clock_gettime(CLOCK_REALTIME, &now);
405	      *waited_ms_out = myvendor_lcd_elapsed_ms(&t0, &now);
406	    }
407	
408	  return true;
409	}
