440	    {
441	      bool expected = false;
442	
443	      if (atomic_compare_exchange_strong_explicit(&g_ui_flush_stack_busy[i],
444	              &expected, true, memory_order_acq_rel, memory_order_acquire))
445	        {
446	          slot = i;
447	          break;
448	        }
449	    }
450	
451	  if (slot < 0)
452	    {
453	      syslog(LOG_ERR, "myvendor_lcd_disp: no free ui_flush stack");
454	      return -ENOMEM;
455	    }
456	
457	  g_lcd_disp.running = true;
458	
459	  pthread_attr_init(&attr);
460	  ret = pthread_attr_setstack(&attr, g_ui_flush_stack[slot],
461	      sizeof(g_ui_flush_stack[slot]));
462	  if (ret == 0)
463	    {
464	      ret = pthread_create(&g_lcd_disp.worker, &attr,
465	          myvendor_lcd_worker_entry, (void *)(intptr_t)slot);
466	    }
467	
468	  pthread_attr_destroy(&attr);
469	
470	  if (ret != 0)
471	    {
472	      g_lcd_disp.running = false;
473	      atomic_store_explicit(&g_ui_flush_stack_busy[slot], false,
474	          memory_order_release);
475	      syslog(LOG_ERR, "myvendor_lcd_disp: worker create failed %d", ret);
476	      return -ret;
477	    }
478	
479	#ifndef CONFIG_DISABLE_PTHREAD
480	  pthread_setname_np(g_lcd_disp.worker, "ui_flush");
481	#endif
482	
483	  return 0;
484	}
