526	/** @brief recover：detach 卡住的 worker（不 cancel）。 */
527	static void myvendor_lcd_stop_worker_force(void)
528	{
529	  pthread_t worker;
530	  int lcd_fd;
531	
532	  pthread_mutex_lock(&g_lcd_disp.lock);
533	  g_lcd_disp.running = false;
534	  worker = g_lcd_disp.worker;
535	  lcd_fd = g_lcd_disp.lcd_fd;
536	  pthread_cond_broadcast(&g_lcd_disp.job_cond);
537	  pthread_cond_broadcast(&g_lcd_disp.idle_cond);
538	  pthread_mutex_unlock(&g_lcd_disp.lock);
539	
540	  if (worker == 0)
541	    {
542	      return;
543	    }
544	
545	  myvendor_lcd_abort_hw_xfer(lcd_fd);
546	  usleep(MYVENDOR_LCD_ABORT_GRACE_MS * 1000u);
547	  myvendor_lcd_abort_hw_xfer(lcd_fd);
548	
549	  /* Drop /dev/lcd0 so a stuck PUTAREA ioctl can return. */
550	  if (lcd_fd >= 0)
551	    {
552	      close(lcd_fd);
553	    }
554	
555	  pthread_mutex_lock(&g_lcd_disp.lock);
556	  if (g_lcd_disp.lcd_fd == lcd_fd)
557	    {
558	      g_lcd_disp.lcd_fd = -1;
559	    }
560	
561	  pthread_mutex_unlock(&g_lcd_disp.lock);
562	
563	  /* Do not pthread_cancel — worker may hold or be unlocking g_lcd_disp.lock.
564	   * Stale worker exits via pthread_self() != g_lcd_disp.worker after PUTAREA. */
565	  pthread_detach(worker);
566	
567	  pthread_mutex_lock(&g_lcd_disp.lock);
568	  if (g_lcd_disp.worker == worker)
569	    {
570	      g_lcd_disp.worker = 0;
571	    }
572	
573	  pthread_mutex_unlock(&g_lcd_disp.lock);
574	  syslog(LOG_ERR, "[lcd_flush] ui_flush detached (recover, no cancel)");
575	}
