596	/**
597	 * End-of-job: clear worker_active and broadcast idle_cond under lock.
598	 * Returns true if this pthread is still the active ui_flush worker and
599	 * may continue the job loop.
600	 */
601	static bool myvendor_lcd_worker_job_done(
602	    const struct myvendor_lcd_flush_job_s *local, bool call_done_cb)
603	{
604	  bool stale = false;
605	
606	  if (g_lcd_disp.worker == 0 || pthread_self() != g_lcd_disp.worker)
607	    {
608	      stale = true;
609	    }
610	  else if (local != NULL &&
611	           local->recover_gen != g_lcd_disp.recover_gen)
612	    {
613	      stale = true;
614	    }
615	
616	  pthread_mutex_lock(&g_lcd_disp.lock);
617	
618	  if (!stale &&
619	      (pthread_self() != g_lcd_disp.worker ||
620	       (local != NULL &&
621	        local->recover_gen != g_lcd_disp.recover_gen) ||
622	       !g_lcd_disp.running))
623	    {
624	      stale = true;
625	    }
626	
627	  atomic_store_explicit(&g_lcd_disp.worker_active, false,
628	      memory_order_release);
629	  pthread_cond_broadcast(&g_lcd_disp.idle_cond);
630	  pthread_mutex_unlock(&g_lcd_disp.lock);
631	
632	  if (stale)
633	    {
634	      if (local != NULL &&
635	          local->recover_gen != g_lcd_disp.recover_gen)
636	        {
637	          syslog(LOG_ERR,
638	              "[lcd_flush] ui_flush stale gen=%u (now %u) — exit",
639	              (unsigned)local->recover_gen,
640	              (unsigned)g_lcd_disp.recover_gen);
641	        }
642	      else if (g_lcd_disp.worker != 0 &&
643	               pthread_self() != g_lcd_disp.worker)
644	        {
645	          syslog(LOG_ERR, "[lcd_flush] ui_flush stale thread — exit");
646	        }
647	
648	      return false;
649	    }
650	
651	  atomic_store_explicit(&g_lcd_disp.recover_refr_armed, false,
652	      memory_order_release);
653	
654	  if (call_done_cb && local != NULL && local->valid &&
655	      g_lcd_disp.running &&
656	      pthread_self() == g_lcd_disp.worker)
657	    {
658	      myvendor_lcd_invoke_done_cb();
659	    }
660	
661	  return g_lcd_disp.running && pthread_self() == g_lcd_disp.worker;
662	}
663	
664	static void *myvendor_lcd_worker_entry(void *arg)
665	{
666	  int slot = (int)(intptr_t)arg;
667	
668	#ifndef CONFIG_DISABLE_PTHREAD
669	  pthread_setcancelstate(PTHREAD_CANCEL_DISABLE, NULL);
670	#endif
671	
672	  while (1)
673	    {
674	      struct myvendor_lcd_flush_job_s local;
675	
676	      if (g_lcd_disp.worker == 0 ||
677	          pthread_self() != g_lcd_disp.worker)
678	        {
679	          goto out;
680	        }
681	
682	      pthread_mutex_lock(&g_lcd_disp.lock);
683	
684	      while (g_lcd_disp.running && !g_lcd_disp.job_ready)
685	        {
686	          pthread_cond_wait(&g_lcd_disp.job_cond, &g_lcd_disp.lock);
687	        }
688	
689	      if (!g_lcd_disp.running)
690	        {
691	          pthread_mutex_unlock(&g_lcd_disp.lock);
692	          goto out;
693	        }
694	
695	      if (pthread_self() != g_lcd_disp.worker)
696	        {
697	          pthread_mutex_unlock(&g_lcd_disp.lock);
698	          goto out;
699	        }
700	
701	      local = g_lcd_disp.job;
702	      g_lcd_disp.job_ready = false;
703	      atomic_store_explicit(&g_lcd_disp.worker_active, true,
704	          memory_order_release);
705	      pthread_mutex_unlock(&g_lcd_disp.lock);
706	
707	      if (local.valid && g_lcd_disp.lcd_fd >= 0)
708	        {
709	          struct timespec t0;
710	          struct timespec t1;
711	          uint32_t put_ms;
712	          int ret;
713	
714	          clock_gettime(CLOCK_MONOTONIC, &t0);
715	          ret = myvendor_lcd_putarea_locked(&local);
716	          clock_gettime(CLOCK_MONOTONIC, &t1);
717	
718	          put_ms = myvendor_lcd_elapsed_ms(&t0, &t1);
719	
720	          if (put_ms > atomic_load_explicit(&g_lcd_disp.stat_putarea_ms_max,
721	                  memory_order_relaxed))
722	            {
723	              atomic_store_explicit(&g_lcd_disp.stat_putarea_ms_max, put_ms,
724	                  memory_order_relaxed);
725	            }
726	
727	          if (put_ms >= MYVENDOR_LCD_PUTAREA_SLOW_MS)
728	            {
729	              atomic_fetch_add_explicit(&g_lcd_disp.stat_putarea_slow, 1,
730	                  memory_order_relaxed);
731	              syslog(LOG_WARNING,
732	                  "[lcd_flush] PUTAREA slow %ums area=(%d,%d)-(%d,%d)",
733	                  (unsigned)put_ms,
734	                  (int)local.area.x1, (int)local.area.y1,
735	                  (int)local.area.x2, (int)local.area.y2);
736	            }
737	
738	          if (ret < 0)
739	            {
740	              atomic_fetch_add_explicit(&g_lcd_disp.stat_putarea_fail, 1,
741	                  memory_order_relaxed);
742	              syslog(LOG_ERR, "myvendor_lcd_disp: PUTAREA failed %d", ret);
743	            }
744	        }
745	
746	      atomic_fetch_add_explicit(&g_lcd_disp.stat_worker_done, 1,
747	          memory_order_relaxed);
748	
749	      if (!myvendor_lcd_worker_job_done(&local, true))
750	        {
751	          goto out;
752	        }
753	    }
754	
755	out:
756	  if (slot >= 0 && slot < 2)
757	    {
758	      atomic_store_explicit(&g_ui_flush_stack_busy[slot], false,
759	          memory_order_release);
760	    }
761	
762	  return NULL;
763	}
