798	  ret = ioctl(g_lcd_disp.lcd_fd, LCDDEVIO_GETVIDEOINFO,
799	              (unsigned long)(uintptr_t)&vinfo);
800	  if (ret < 0)
801	    {
802	      syslog(LOG_ERR, "myvendor_lcd_disp: GETVIDEOINFO failed %d", ret);
803	      goto errout;
804	    }
805	
806	  g_lcd_disp.hor_res = (uint16_t)vinfo.xres;
807	  g_lcd_disp.ver_res = (uint16_t)vinfo.yres;
808	
809	  if (g_lcd_disp.hor_res == 0 || g_lcd_disp.ver_res == 0)
810	    {
811	      syslog(LOG_ERR, "myvendor_lcd_disp: bad resolution %ux%u",
812	             g_lcd_disp.hor_res, g_lcd_disp.ver_res);
813	      ret = -EINVAL;
814	      goto errout;
815	    }
816	
817	  g_lcd_disp.strip_rows = (uint16_t)CONFIG_MYVENDOR_LCD_DISP_STRIP_ROWS;
818	
819	  if (g_lcd_disp.strip_rows < 8)

819	  if (g_lcd_disp.strip_rows < 8)
820	    {
821	      g_lcd_disp.strip_rows = 8;
822	    }
823	
824	  if (g_lcd_disp.strip_rows > g_lcd_disp.ver_res)
825	    {
826	      g_lcd_disp.strip_rows = g_lcd_disp.ver_res;
827	    }
828	
829	  g_lcd_disp.stride = (uint32_t)g_lcd_disp.hor_res * 2u;
830	  g_lcd_disp.buf_bytes = (size_t)g_lcd_disp.stride * g_lcd_disp.strip_rows;
831	
832	  if (g_lcd_disp.buf_bytes == 0)
833	    {
834	      syslog(LOG_ERR, "myvendor_lcd_disp: strip size is zero");
835	      ret = -EINVAL;
836	      goto errout;
837	    }
838	
839	  if (pthread_mutex_init(&g_lcd_disp.lock, NULL) != 0 ||
840	      pthread_cond_init(&g_lcd_disp.job_cond, NULL) != 0 ||
841	      pthread_cond_init(&g_lcd_disp.idle_cond, NULL) != 0)
842	    {
843	      syslog(LOG_ERR, "myvendor_lcd_disp: pthread sync init failed");
844	      ret = -EIO;
845	      goto errout;
846	    }
847	
848	  g_lcd_disp.sync_inited = true;
849	  ret = myvendor_lcd_start_worker();
850	  if (ret < 0)
851	    {
852	      goto errout;
853	    }
854	
855	  g_lcd_disp.inited = true;
856	
857	  syslog(LOG_INFO,
858	         "myvendor_lcd_disp: %ux%u strip=%u stride=%lu direct-sram path=%s "
859	         "(ui_flush double-buffer)",
860	         g_lcd_disp.hor_res, g_lcd_disp.ver_res, g_lcd_disp.strip_rows,
861	         (unsigned long)g_lcd_disp.stride, lcd_path);
862	
863	  return 0;
864	
865	errout:
866	  myvendor_lcd_disp_deinit();
867	  return ret;
868	}
