1002	static int myvendor_lcd_disp_recover(void)
1003	{
1004	  if (!g_lcd_disp.inited || !g_lcd_disp.sync_inited)
1005	    {
1006	      return -ENODEV;
1007	    }
1008	
1009	  if (atomic_exchange_explicit(&g_lcd_disp.recover_in_progress, true,
1010	          memory_order_acq_rel))
1011	    {
1012	      return -EBUSY;
1013	    }
1014	
1015	  syslog(LOG_ERR, "[lcd_flush] RECOVER: abort DMA, stop worker, restart pipe");
1016	
1017	  {
1018	    uint32_t now = myvendor_lcd_mono_ms();
1019	
1020	    atomic_store_explicit(&g_lcd_disp.recover_quiet_until_ms,
1021	        now + MYVENDOR_LCD_RECOVER_COOLDOWN_MS, memory_order_release);
1022	    atomic_store_explicit(&g_lcd_disp.busy_since_ms, now, memory_order_release);
1023	  }
1024	
1025	  pthread_mutex_lock(&g_lcd_disp.lock);
1026	  g_lcd_disp.recover_gen++;
1027	  g_lcd_disp.job_ready = false;
1028	  g_lcd_disp.running = false;
1029	  memset(&g_lcd_disp.job, 0, sizeof(g_lcd_disp.job));
1030	  pthread_cond_broadcast(&g_lcd_disp.job_cond);
1031	  pthread_cond_broadcast(&g_lcd_disp.idle_cond);
1032	  pthread_mutex_unlock(&g_lcd_disp.lock);
1033	
1034	  atomic_store_explicit(&g_lcd_disp.worker_active, false,
1035	      memory_order_release);
1036	
1037	  /* Abort DMA, detach stuck ui_flush (never pthread_join — ioctl may not return). */
