1076	 * @brief 提交一条 LVGL 条带到 worker。
1077	 * @return 0 成功；-EBUSY/-EIO/-EINVAL。
1078	 */
1079	int myvendor_lcd_disp_submit_flush(const myvendor_lcd_disp_area_t *area,
1080	                                   const void *color_p,
1081	                                   uint32_t stride_bytes,
1082	                                   bool is_last)
1083	{
1084	  uint32_t waited_ms = 0;
1085	
1086	  (void)is_last;
1087	
1088	  if (!g_lcd_disp.inited || g_lcd_disp.lcd_fd < 0 ||
1089	      area == NULL || color_p == NULL)
1090	    {
1091	      atomic_fetch_add_explicit(&g_lcd_disp.stat_submit_err, 1,
1092	          memory_order_relaxed);
1093	      return -EINVAL;
1094	    }
1095	
1096	  if (atomic_load_explicit(&g_lcd_disp.recover_hold_submit,
1097	          memory_order_acquire))
1098	    {
1099	      return 0;
1100	    }
1101	
1102	  /* Wait for previous strip DMA so the other SRAM buffer can be submitted. */
1103	  if (!myvendor_lcd_disp_wait_idle(0, &waited_ms))
1104	    {
1105	      atomic_fetch_add_explicit(&g_lcd_disp.stat_submit_err, 1,
1106	          memory_order_relaxed);
1107	      return -EIO;
1108	    }
1109	
1110	  myvendor_lcd_disp_poll_recover_unblock();
1111	
1112	  if (atomic_load_explicit(&g_lcd_disp.recover_hold_submit,
1113	          memory_order_acquire))
1114	    {
1115	      return 0;
1116	    }
1117	
1118	  pthread_mutex_lock(&g_lcd_disp.lock);
1119	
1120	  if (lcd_disp_is_busy_locked())
1121	    {
1122	      pthread_mutex_unlock(&g_lcd_disp.lock);
1123	      atomic_fetch_add_explicit(&g_lcd_disp.stat_submit_busy, 1,
1124	          memory_order_relaxed);
1125	      return -EBUSY;
1126	    }
1127	
1128	  g_lcd_disp.job.valid = true;
1129	  g_lcd_disp.job.area  = *area;
1130	  g_lcd_disp.job.data  = (const uint8_t *)color_p;
1131	  g_lcd_disp.job.stride = stride_bytes;
1132	  g_lcd_disp.job.is_last = is_last;
1133	  g_lcd_disp.job.recover_gen = g_lcd_disp.recover_gen;
1134	  g_lcd_disp.job_ready = true;
1135	  myvendor_lcd_note_busy();
1136	
1137	  pthread_cond_signal(&g_lcd_disp.job_cond);
1138	  pthread_mutex_unlock(&g_lcd_disp.lock);
1139	
1140	  atomic_fetch_add_explicit(&g_lcd_disp.stat_submit_ok, 1,
1141	      memory_order_relaxed);
1142	  return 0;
1143	}
