6207	bool myvendor_gnss_get(myvendor_sys_gnss_t *out)
6208	{
6209	  bool ok = false;
6210	  bool hold;
6211	  uint32_t now = gnss_now_ms();
6212	
6213	  pthread_mutex_lock(&g_lock);
6214	  hold = gnss_hold_locked(now);
6215	  if (g_fix.alive && g_fix_ms != 0 &&
6216	      (hold || gnss_elapsed_ms(now, g_fix_ms) < GNSS_STALE_MS)) {
6217	    if (out != NULL) {
6218	      *out = g_fix;
6219	      out->alive = true;
6220	      out->rx_hz = hold ? g_fix.rx_hz : gnss_rx_hz_now(now);
6221	    }
6222	
6223	    ok = true;
6224	  } else if (hold) {
6225	    if (out != NULL) {
6226	      if (g_fix_ms != 0) {
6227	        *out = g_fix;
6228	      } else {
6229	        memset(out, 0, sizeof(*out));
6230	      }
6231	
6232	      out->alive = true;
6233	    }
6234	
6235	    ok = true;
6236	  }
6237	
6238	  pthread_mutex_unlock(&g_lock);
6239	  if (!ok && out != NULL) {
6240	    memset(out, 0, sizeof(*out));
6241	  }
6242	
6243	  if (ok) {
6244	    if (!g_get_ok) {
6245	      syslog(LOG_INFO, "gnss: snapshot live (UI) hz=%u valid=%d sats=%u\n",
6246	             (unsigned)(out != NULL ? out->rx_hz : 0),
6247	             (out != NULL && out->valid) ? 1 : 0,
6248	             (unsigned)(out != NULL ? out->satellites : 0));
6249	    }
6250	
6251	    g_get_ok = true;
6252	  } else if (g_get_ok) {
6253	    uint32_t nmea_age = (g_nmea_life_ms == 0) ?
6254	                        0 : gnss_elapsed_ms(now, g_nmea_life_ms);
6255	
6256	    syslog(LOG_WARNING,
6257	           "gnss: snapshot stale (UI 无数据) nmea_age=%u fail=%u recov=%d\n",
6258	           (unsigned)nmea_age, (unsigned)g_uart_fails,
6259	           g_recovering ? 1 : 0);
6260	    g_get_ok = false;
6261	  }
6262	
6263	  return ok;
6264	}
