6266	static uint32_t gnss_eph_scan_best_utc(void)
6267	{
6268	  DIR *dir;
6269	  struct dirent *de;
6270	  char path[GNSS_EPH_PATH_MAX];
6271	  uint32_t best = 0;
6272	  uint32_t utc;
6273	  int n;
6274	
6275	  dir = opendir(SF32LB52_GNSS_EPH_DIR);
6276	  if (dir != NULL) {
6277	    while ((de = readdir(dir)) != NULL) {
6278	      if (!gnss_eph_parse_utc(de->d_name, &utc) || utc < best) {
6279	        continue;
6280	      }
6281	
6282	      n = snprintf(path, sizeof(path), "%s/%s",
6283	                   SF32LB52_GNSS_EPH_DIR, de->d_name);
6284	      if (n < 0 || n >= (int)sizeof(path)) {
6285	        continue;
6286	      }
6287	
6288	      if (!gnss_eph_path_usable(path)) {
6289	        continue;
6290	      }
6291	
6292	      best = utc;
6293	    }
6294	
6295	    closedir(dir);
6296	  }
6297	
6298	  if (best == 0 && gnss_eph_path_usable(SF32LB52_GNSS_EPH_FILE)) {
6299	    struct stat st;
6300	
6301	    if (stat(SF32LB52_GNSS_EPH_FILE, &st) == 0 &&
6302	        st.st_mtime >= (time_t)GNSS_TIME_MIN_UNIX) {
6303	      best = (uint32_t)st.st_mtime;
6304	    }
6305	  }
6306	
6307	  return best;
6308	}
