6310	bool myvendor_gnss_eph_times(uint32_t *last_utc, uint32_t *next_utc)
6311	{
6312	  uint32_t last;
6313	  uint32_t now;
6314	
6315	  now = gnss_now_ms();
6316	  pthread_mutex_lock(&g_lock);
6317	  if (g_eph_times_ms != 0 &&
6318	      gnss_elapsed_ms(now, g_eph_times_ms) < GNSS_EPH_TIMES_CACHE_MS) {
6319	    last = g_eph_times_cached;
6320	    pthread_mutex_unlock(&g_lock);
6321	  } else {
6322	    pthread_mutex_unlock(&g_lock);
6323	    last = gnss_eph_scan_best_utc();
6324	    pthread_mutex_lock(&g_lock);
6325	    if (g_eph_last_utc > last) {
6326	      last = g_eph_last_utc;
6327	    } else {
6328	      g_eph_last_utc = last;
6329	    }
6330	
6331	    g_eph_times_cached = last;
6332	    g_eph_times_ms = gnss_now_ms();
6333	    pthread_mutex_unlock(&g_lock);
6334	  }
6335	
6336	  if (last_utc != NULL) {
6337	    *last_utc = last;
6338	  }
6339	
6340	  if (next_utc != NULL) {
6341	    *next_utc = (last != 0) ? last + GNSS_EPH_VALID_SEC : 0;
6342	  }
6343	
6344	  return last >= (uint32_t)GNSS_TIME_MIN_UNIX;
6345	}
