6399	myvendor_gnss_off_t myvendor_gnss_prepare_poweroff(void)
6400	{
6401	  myvendor_sys_gnss_t fix;
6402	  uint32_t start;
6403	
6404	  if (!g_started) {
6405	    return MYVENDOR_GNSS_OFF_SKIP;
6406	  }
6407	
6408	  if (g_idle_sleep) {
6409	    syslog(LOG_INFO, "gnss: skip dbd dump at poweroff (idle sleep)\n");
6410	    return MYVENDOR_GNSS_OFF_SKIP_IDLE;
6411	  }
6412	
6413	  if (myvendor_is_factory()) {
6414	    syslog(LOG_INFO, "gnss: skip dbd dump at poweroff (factory)\n");
6415	    return MYVENDOR_GNSS_OFF_SKIP_FACTORY;
6416	  }
6417	
6418	  if (!myvendor_devctl_eph_auto_get()) {
6419	    syslog(LOG_INFO, "gnss: skip dbd dump at poweroff (eph auto off)\n");
6420	    return MYVENDOR_GNSS_OFF_SKIP_AUTO;
6421	  }
6422	
6423	  if (!myvendor_gnss_get(&fix) || !fix.valid) {
6424	    syslog(LOG_INFO, "gnss: skip dbd dump at poweroff (no fix)\n");
6425	    return MYVENDOR_GNSS_OFF_SKIP_NOFIX;
6426	  }
6427	
6428	  pthread_mutex_lock(&g_lock);
6429	  g_dump_halt = true;
6430	  g_dump_req = true;
6431	  g_dump_done = false;
6432	  pthread_mutex_unlock(&g_lock);
6433	
6434	  /* 倒库在 GNSS 线程；这里只等到完成。无 DBD 时线程 5 秒会 mark_done。 */
6435	  start = gnss_now_ms();
6436	  while (gnss_elapsed_ms(gnss_now_ms(), start) < 12000u) {
6437	    bool done;
6438	    uint32_t elapsed;
6439	
6440	    pthread_mutex_lock(&g_lock);
6441	    done = g_dump_done;
6442	    pthread_mutex_unlock(&g_lock);
6443	    if (done) {
6444	      return MYVENDOR_GNSS_OFF_DUMPED;
6445	    }
6446	
6447	    elapsed = gnss_elapsed_ms(gnss_now_ms(), start);
6448	    if (g_dbd_n < (int)GNSS_DBD_MIN_FRAMES && elapsed >= GNSS_DBD_NODATA_MS) {
6449	      syslog(LOG_INFO, "gnss: skip dbd dump at poweroff (no data 5s)\n");
6450	      return MYVENDOR_GNSS_OFF_SKIP_NODATA;
6451	    }
6452	
6453	    myvendor_watchdog_ui_beat();
6454	    myvendor_watchdog_work_beat();
6455	    myvendor_watchdog_hw_pet();
6456	    gnss_sleep_ms(20);
6457	  }
6458	
6459	  syslog(LOG_WARNING, "gnss: dbd dump timeout at poweroff\n");
6460	  return MYVENDOR_GNSS_OFF_TIMEOUT;
6461	}
